INSERT INTO movie (title, description, production_date) VALUES
                                                            ('Incepcja', 'Dom Cobb to wybitny specjalista w niezwykle niebezpiecznej dziedzinie szpiegostwa przemysłowego: ekstrakcji. Kradnie on bezcenne sekrety z najgłębszych zakamarków ludzkiej podświadomości podczas fazy snu, kiedy umysł jest najbardziej bezbronny. Choć jego niezwykłe umiejętności uczyniły go najbardziej pożądanym graczem w zdradzieckim świecie korporacyjnego szpiegostwa, sprawiły również, że stał się międzynarodowym zbiegiem, który stracił wszystko, co kochał. Teraz Cobb otrzymuje szansę na odkupienie. Ostatnie zadanie może przywrócić mu dawne życie, ale tylko pod warunkiem, że dokona niemożliwego – incepcji. Zamiast idealnej kradzieży, Cobb i jego zespół specjalistów muszą zaszczepić nową ideę w umyśle celu. Jeśli im się uda, będzie to zbrodnia doskonała. Jednak żadne planowanie nie jest w stanie przygotować ich na spotkanie z niebezpiecznym wrogiem, który zdaje się przewidywać każdy ich ruch.', '2010-07-16'),
INSERT INTO category (name, description) VALUES
                                             ('Sci-Fi', 'Filmy fantastycznonaukowe, alternatywne rzeczywistości, zaawansowana technologia'),
                                             ('Thriller', 'Trzymające w napięciu thrillery psychologiczne i sensacyjne'),
                                             ('Kryminał', 'Historie gangsterskie, mafijne porachunki i świat przestępczy'),
                                             ('Dramat', 'Głębokie wątki osobiste, konflikty moralne i dramatyczne wybory życiowe'),
                                             ('Akcja', 'Szybkie tempo, widowiskowe starcia i pościgi'),
                                             ('Fantasy', 'Magiczne światy, epickie wyprawy i mityczne stworzenia'),
                                             ('Biograficzny', 'Historie oparte na faktach, przedstawiające losy autentycznych postaci'),
                                             ('Muzyczny', 'Filmy skupione wokół muzyki, tańca i historii artystów');
